  "deleteAccountCancelsSubNote": "إذا كان لديك اشتراك نشط، فسيُلغى تلقائيًا عند حذف الحساب ولن تُحصَّل منك رسوم مجددًا. هذا الإجراء لا يمكن التراجع عنه.",
