  "tweezersBottomName": "قاع الملقط",
  "tweezersBottomDesc": "شمعتان متتاليتان بقيعان متطابقة. إشارة على دعم قوي واهتمام شرائي عند ذلك المستوى السعري.",
  "tweezersTopName": "قمة الملقط",
  "tweezersTopDesc": "شمعتان متتاليتان بقمم متطابقة. إشارة على مقاومة قوية واهتمام بيعي عند ذلك المستوى السعري.",
  "evTitle": "التداول المبني على الأدلة",
  "evIntro": "ما الذي أُثبت فعلًا بالبيانات لا بالوعود؟ نجمع هنا ما تُظهره الدراسات الأكاديمية والجهات التنظيمية وقرن من بيانات الصناديق والبنوك ومكاتب التداول: كم يخسر الناس حقًا، وأي الاستراتيجيات صمدت عقودًا أمام الإحصاء، وكيف يدير المحترفون المخاطر. الخيط الناظم هو قانون الأعداد الكبيرة: صفقة واحدة حظّ؛ وألف صفقة إحصاء.",
  "hzTitle": "الجلسات والموسمية",
  "hzIntro": "في ساعات وتواريخ معيّنة يميل السوق للتصرّف بطرق متشابهة بسبب تدفّقات المال (الافتتاح، البيانات، الإغلاق، الاستحقاقات). ليست قواعد ثابتة ولا إشارات شراء: بل ميول إحصائية تساعدك على اختيار متى تتداول ومتى تبتعد. كل الأوقات بتوقيت فرانكفورت / UTC+2 (تتغيّر ±ساعة مع التوقيت الصيفي).",
  "msTitle": "بنية السوق",
  "msIntro": "قبل أي نموذج، السعر سلسلة من القمم والقيعان. قراءة البنية — هل تصعد هذه القمم والقيعان أم تهبط أم تتحرّك جانبيًا — تخبرك بالاتجاه ومن المسيطر. إنها الأساس الذي تقوم عليه النماذج السعرية وSMC وكل شيء تقريبًا. هنا تتعلّم قراءتها وكشف متى تتغيّر.",
  "mcTitle": "الماكرو: الدورة والفائدة والتدوير",
  "mcIntro": "الخلفية الكلية تحرّك أسواقًا بأكملها — أكثر من أي رسم بياني منفرد. أسعار الفائدة والتضخم والنمو تحدّد المدّ الذي يرفع كل القوارب أو يُغرقها. الأمر ليس تنبؤًا بل تموضعًا: أن تعرف في أي مرحلة من الدورة نحن، وما الذي ينجح فيها عادةً.",
  "cvTitle": "تقييم شركة بعمق",
  "cvIntro": "يبحث التحليل الأساسي عمّا تساويه الشركة فعلاً ويقارنه بسعرها في السوق. السعر ≠ القيمة: شركة عظيمة قد تكون استثمارًا سيئًا إن دفعت زيادة، وأخرى متواضعة قد تكون صفقة. هنا تتعلّم قراءة أرقامها وتقدير قيمتها — أبعد من النِّسب الأربع الأساسية.",
  "ofTitle": "تدفق الأوامر / قراءة الشريط",
  "ofIntro": "السعر نتيجة، وتدفق الأوامر هو السبب. هنا تتعلّم قراءة ضغط الشراء والبيع الحقيقي — من المُبادِر، وأين السيولة، وأين تُمتَص — بدل النظر إلى الشمعة المكتملة فقط. يحتاج بيانات المستوى الثاني وممارسة، لكنه عدسة متداولي اليوم المحترفين.",
  "protoTitle": "بروتوكول ما قبل التداول",
  "protoIntro": "ثلاث أدوات لتحويل الانضباط إلى قواعد ملموسة: قواطعك، ومرشّح الدخول، وفحص ذهني. استخدمها بهذا الترتيب قبل كل جلسة وكل صفقة.",
  "brkTitle": "قواعد التوقف (القواطع)",
  "brkIntro": "قرّر مسبقًا كم يمكنك أن تخسر قبل أن تُغلق المنصة. وعندما ينطلق أحد الحدود، انتهى يومك: بلا استثناءات، وبلا 'صفقة أخيرة'.",
