  "ideskTitle": "مكتب التداول المؤسسي",
  "ideskIntro": "البنك أو الصندوق لا «يتداول» كالأفراد: يوزّع العمل بين متخصصين، بعمليات وحدود وتقنية. هنا ترى كيف يعمل مكتب احترافي من الداخل، وما الذي يمكنك سرقته من كل دور لتتداول كمحترف حتى وأنت وحدك في البيت.",
  "discTitle": "الانضباط والأداء الاحترافي",
  "discIntro": "ما يفصل المحترف الرابح عن الفرد الذي يحرق حسابه ليس المؤشر السري، بل كيف يديرون عقولهم وأخطاءهم وضغطهم تحت الضغط. هذا هو «برنامج» المتداول النخبة، المستعار من المكاتب المؤسسية والطيارين والجراحين ورياضيي الأداء العالي.",
  "mstTitle": "اختبار ضغط الهامش",
  "mstIntro": "قبل فتح صفقة برافعة، تحقق مما إذا كنت ستنجو من هبوط حاد. أدخل رصيدك ومراكزك وسترى، سيناريو تلو الآخر، كم تخسر وكم يتبقى من رصيد وهل يقع نداء الهامش أو التصفية. السؤال الجوهري: «هل أنجو من −20%؟».",
