  "flowIntroDesc_mf001": "اضغط {scan} للكشف عن النشاط غير المعتاد في SPY، QQQ، TSLA، NVDA، AAPL، META و18 رمزًا إضافيًا. مرتبة حسب القيمة الاسمية ($).",
