  "testimonial3Quote_l030": "أستخدمه يومياً منذ 8 أشهر. Monte Carlo والمفكرة غيّرا نظرتي للمخاطر. 5 نجوم.",
  "testimonial3Author_l031": "David L.",
  "testimonial3Role_l032": "متداول مستقل · Forex",
  "faqQ1_l040": "هل أحتاج أن أكون خبيراً لاستخدامه؟",
  "faqA1_l041": "لا. التطبيق يرشدك خطوة بخطوة في كل آلة حاسبة، وEducation Center يغطي من الأساسيات (ما هو Stop Loss) إلى الاستراتيجيات المتقدمة بالخيارات. يوجد Demo Trader مجاني لتجربة كل شيء دون مخاطرة.",
  "faqQ2_l050": "هل يمكنني إلغاء الاشتراك متى أردت؟",
  "faqA2_l051": "نعم. ألغِ بنقرة واحدة من ملفك الشخصي. لا توجد مدة التزام. إذا اشتريت Lifetime، يكون الوصول دائماً — دون مدفوعات متكررة.",
  "faqQ3_l060": "ما الأصول المدعومة؟",
  "faqA3_l061": "العملات المشفرة، Forex، الأسهم الأمريكية (NYSE/NASDAQ)، المؤشرات (SPX، NDX، DAX، إلخ)، السلع والعقود الآجلة. بيانات العملات المشفرة فورية؛ قد تتأخر الأسواق الأخرى.",
  "faqQ4_l070": "هل الذكاء الاصطناعي في Trade Coach مدفوع بشكل منفصل؟",
  "faqA4_l071": "لا. AI Trade Coach (Claude Sonnet 4.5) مُضمّن في جميع خطط Premium. يحلل استراتيجيتك، يحدد المخاطر ويقترح تحسينات كموجّه متمرس.",
