  "optTitle": "استراتيجيات الخيارات",
  "optIntro": "الجمع بين الكول والبوت يتيح بناء مراكز بمخاطرة محددة والربح ليس من الاتجاه فقط، بل أيضًا من التقلب وتآكل الوقت. استخدم حاسبة الخيارات لرؤية الإغريق ومخطط العائد لكل استراتيجية.",
  "smcIntro": "نهج 'المال الذكي' (الذي نشره ICT) يحاول تتبّع آثار المال المؤسسي: أين يبنون الأوامر، وكيف يصطادون سيولة الأفراد، وأين يعود السعر. إنه اجتهادي — استخدمه كتقاطع تأكيدي، لا كنظام سحري.",
  "ichiIntro": "مخطط 'التوازن بنظرة واحدة' الياباني، ابتكره غويتشي هوسودا. خمسة خطوط و'سحابة' مُسقطة تُظهر معًا الاتجاه والدعم/المقاومة والزخم وإشارات الدخول — صُمّم لقراءة السوق بنظرة واحدة. شائع جدًا في الفوركس والعملات الرقمية.",
  "ewTitle": "نظرية موجات إليوت",
  "ewIntro": "لاحظ رالف إليوت أن سيكولوجيا الجماهير تحرّك الأسواق في أنماط موجية متكررة. يتقدّم السعر في تسلسل 'دافع' من 5 موجات باتجاه الاتجاه، ثم يصحّح في تسلسل من 3 موجات عكسه. يتكرّر الشكل نفسه 5-3 في كل درجة، من الدقائق إلى العقود.",
