  "cmtKellyIntro": "نسبة كيلي هي النسبة المثلى رياضيًا من رأس المال التي ينبغي المخاطرة بها بحسب أفضليتك. كيلي الكامل يعظّم النمو على المدى الطويل لكنه شديد التقلب — والمحترفون يستخدمون جزءًا منه فقط.",
