  "cmtPayoff": "Payoff ratio",
  "cmtExpectancy": "Expectancy",
  "cmtNoEdge": "بهذه المدخلات ليس للنظام أفضلية إيجابية — كيلي سالب، أي أنه لا ينبغي أن تخاطر بشيء حتى تتحسّن نسبة الصفقات الرابحة أو نسبة الربح إلى الخسارة.",
  "cmtKellyTip": "المخاطرة بكيلي الكامل تنتج عادةً تراجعات تتجاوز 50%. معظم المحترفين يستخدمون نصف كيلي أو ربعه لالتقاط معظم النمو بتقلّب أقل بكثير.",
  "slGuideTitle": "وقف الخسارة: ثابت أم متغيّر",
  "slGuideIntro": "موضع الوقف هو ما يحدد مخاطرتك، ومضاعف R لديك، وفي النهاية توقعك الرياضي. الوقف الموضوع وفق بنية السوق يتكيّف مع الواقع؛ أما الوقف الثابت الاعتباطي فيصارعه.",
  "slTypesTitle": "ثلاث طرق لوضع الوقف",
  "slStructureName": "Structure-based",
  "slStructureDesc": "يوضع الوقف خلف القمة/القاع أو الدعم أو المقاومة التي يُبطل كسرها فكرتك بقليل. السوق هو من يخبرك أين أخطأت — أسلوب متكيّف ومنطقي.",
  "slAtrName": "Volatility-based (ATR)",
  "slAtrDesc": "مسافة الوقف = مضاعف من ATR (مثلًا 1.5×ATR). تتّسع في الأوقات المتقلبة وتضيق في الهادئة، فلا يخرجك الضجيج الطبيعي.",
  "slFixedName": "Fixed (pips / %)",
  "slFixedDesc": "المسافة نفسها دائمًا (مثلًا 20 نقطة أو 2%) بغض النظر عن البنية أو التقلب. بسيط، لكنه يتجاهل الموضع الذي تُبطل عنده الصفقة فعلًا — وعلى عيّنة كبيرة يقضم التوقع الرياضي بصمت.",
  "slBreakevenTitle": "الحد الأدنى لنسبة العائد إلى المخاطرة ليس واحدًا للجميع",
  "slBreakevenIntro": "نسبة العائد إلى المخاطرة عند التعادل تعتمد كليًا على نسبة صفقاتك الرابحة. النظام عالي الدقة يربح حتى دون 1:1؛ ونظام الاتجاه منخفض الدقة يحتاج R كبيرًا. مقولة «استخدم 1:2 دائمًا» خرافة.",
  "slColWinRate": "Win Rate",
  "slColBreakeven": "Break-even R:R",
  "slColProfitable": "Profitable above",
  "slBreakevenFormula": "R عند التعادل = (1 − نسبة الربح) ÷ نسبة الربح",
  "slKeyInsight": "الوقف الثابت الاعتباطي يفرض R ثابتًا قد لا يناسب نسبة ربحك الحقيقية — حتى الإعداد «الجيد» قد يحمل توقعًا سالبًا. ضع الوقف حيث تكون الفكرة خاطئة، وقلّل الحجم لتبقى المخاطرة ثابتة، ودع نسبة العائد إلى المخاطرة تنبع من البنية.",
  "otGuideTitle": "دفتر الأوامر وأنواع الأوامر",
  "otGuideIntro": "كل صفقة تُطابَق في دفتر الأوامر: سُلَّم حي من أوامر الشراء والبيع المعلّقة. فهمه يفسّر الفارق السعري والسيولة والانزلاق — وكذلك الأوامر المخفية التي تستخدمها المؤسسات.",
  "otOrderBookTitle": "Limit Order Book",
  "otSpread": "SPREAD",
  "otAsksLabel": "Asks (offers)",
  "otAsksDesc": "أوامر بيع محدّدة معلّقة فوق السعر؛ أدنى سعر عرض هو أفضل سعر للشراء الآن.",
  "otBidsLabel": "Bids",
  "otBidsDesc": "أوامر شراء محدّدة معلّقة تحت السعر؛ أعلى سعر طلب هو أفضل سعر للبيع الآن.",
  "otDepthLabel": "Depth / liquidity",
  "otDepthDesc": "طول الشريط = الحجم المعلّق عند كل مستوى. العمق الرقيق يعني أن أمر السوق سينزلق عبر عدة مستويات.",
  "otIcebergHint": "الشريط المتقطع هو أمر جبل جليد: لا يظهر منه سوى قمة صغيرة، ويُعاد ملء الباقي كلما نُفِّذ.",
  "otAdvancedTitle": "أنواع الأوامر المؤسسية والمتقدمة",
  "otIcebergName": "Iceberg Order",
  "otIcebergDesc": "أمر كبير لا يُظهر في الدفتر سوى «قمة» صغيرة في كل مرة. كلما نُفِّذت الشريحة الظاهرة كُشِفت التالية تلقائيًا — فيبقى الحجم الحقيقي مخفيًا ولا يتحرك السوق ضد المتعامل الكبير.",
  "otHiddenName": "Hidden / Reserve Order",
  "otHiddenDesc": "غير مرئي إطلاقًا في الدفتر العام — يوفّر سيولة دون أن يكشف النية بتاتًا. يُنفَّذ عادةً بعد الأوامر الظاهرة بالسعر نفسه (أولوية أدنى في الطابور) مقابل تخفٍّ كامل.",
  "otOcoName": "OCO (One-Cancels-Other)",
  "otOcoDesc": "أمران مرتبطان — عادةً جني أرباح ووقف خسارة. حين يُنفَّذ أحدهما يُلغى الآخر تلقائيًا. الطريقة المعتادة لتأطير المركز.",
  "otFokIocName": "FOK / IOC",
  "otFokIocDesc": "«التنفيذ الكامل أو الإلغاء» ينفّذ الحجم كاملًا فورًا أو يُلغى بالكامل؛ و«التنفيذ الفوري وإلغاء الباقي» ينفّذ ما يمكن الآن ويلغي البقية. كلاهما يتجنّب ترك أمر معلّق يكشف نواياك.",
  "dowDiagramTitle": "دورة السوق ومراحلها الثلاث",
  "dowDiagramIntro": "ترى نظرية داو أن السوق الصاعدة الرئيسية تمر بثلاث مراحل نفسية. السعر لا يصعد في خط مستقيم بل على شكل درج من اتجاه رئيسي وردود فعل ثانوية.",
  "dowPhaseAccumulation": "Accumulation",
  "dowPhaseParticipation": "Public Participation",
  "dowPhaseDistribution": "Distribution",
  "dowDegreesTitle": "The three trend degrees",
  "dowDegreePrimaryName": "Primary trend",
  "dowDegreePrimaryDesc": "المد الرئيسي — يستمر شهورًا إلى سنوات. هذا هو الاتجاه الذي تريد التداول معه. ولا ينهيه إلا انعكاس مؤكَّد في المؤشرين معًا.",
  "dowDegreeSecondaryName": "Secondary reaction",
  "dowDegreeSecondaryDesc": "الموجات المعاكسة للمد — تصحيحات تدوم أسابيع وتسترد من ثلث إلى ثلثي الحركة السابقة. هنا يبحث متتبعو الاتجاه عن الدخول.",
  "dowDegreeMinorName": "Minor trend",
