  "optExitOpenEnded": "المنحنى ما زال يصعد عند حافة الرسم: الحد الأقصى المعروض هو حدّ النافذة السعرية لا حدّ الاستراتيجية.",
  "optExitNote": "أسعار عند الاستحقاق مع خصم عمولات الذهاب والإياب. الإغلاق قبل الاستحقاق يترك قيمة زمنية.",
  "calcDescPosition": "كم وحدة تشتري لكي تخسر — عند تفعيل وقف الخسارة — النسبة المئوية من الحساب التي قررت المخاطرة بها بالضبط. هذه الحسبة تُجرى قبل الدخول.",
  "calcDescLotsize": "نفس حساب حجم الصفقة لكن بعقود الفوركس، مع مراعاة قيمة النقطة لكل زوج وعملة حسابك.",
  "calcDescPartialExit": "متوسط سعر الخروج والربح الفعلي عند إغلاق الصفقة على دفعات بدلاً من مرة واحدة.",
  "calcDescLeverage": "عند أي سعر تتم تصفيتك وكم هامشًا يحجزه كل مستوى رافعة. يوضح لك بُعد التصفية قبل فتح الصفقة.",
  "calcDescFutures": "الهامش المطلوب وقيمة النقطة والنتيجة لعقد آجل، بمضاعف كل سوق الخاص.",
  "calcDescTarget": "بأي سعر يجب أن تبيع لتحقيق نسبة الربح المستهدفة، شاملة العمولات.",
  "calcDescPercentage": "كم يجب أن يرتفع الأصل لتعويض هبوط. اللاتماثل مفاجئ: خسارة 50% تتطلب ربح 100% لمجرد العودة إلى نقطة البداية.",
  "calcDescSpot": "كم تستلم فعليًا عند الشراء أو البيع الفوري بعد خصم العمولات.",
  "calcDescMeasure": "هدف السعر الذي يسقطه النموذج السعري من ارتفاعه الخاص — هكذا يُقاس المثلث ونموذج الرأس والكتفين والمستطيل.",
  "calcDescFibonacci": "مستويات تصحيح وامتداد فيبوناتشي بين نقطتين على الرسم البياني، لتحديد الدخول والأهداف.",
  "calcDescPattern": "الدخول ووقف الخسارة والهدف لنموذج سعري محدد، مع نسبة العائد إلى المخاطرة محسوبة.",
  "calcDescMontecarlo": "كيف تتوزع نتائج نظامك إذا أعدت تشغيل نفس الصفقات آلاف المرات بترتيب مختلف. يُظهر سلسلة الخسائر التي تسمح بها إحصاءاتك.",
  "calcDescSimulator": "تطور الحساب على مراحل، بتطبيق قواعد المخاطرة الخاصة بك ومعرفة متى يجب رفع أو خفض حجم الصفقة.",
  "calcDescCompound": "كيف ينمو رأس المال بإعادة استثمار الأرباح، مع الإيداعات الدورية إن وُجدت.",
  "helpAria": "عرض الشرح",
  "helpRiskPerTrade": "النسبة من الحساب التي تقبل خسارتها في «هذه» الصفقة، لا في المجموع. المعتاد بين 1% و2%: عند 2% تلزم نحو 35 خسارة متتالية لتنصيف الحساب، وعند 10% تكفي سبع.",
  "helpStopDistance": "المسافة بين الدخول ووقف الخسارة هي ما يحدد الحجم، لا العكس. الوقف الأضيق يتيح شراء وحدات أكثر بنفس المخاطرة — لكنه يُلمس أكثر.",
  "helpRequiredLeverage": "الرافعة التي ستحتاجها لفتح هذه الصفقة برأس مالك. ليست توصية: إذا خرجت مرتفعة فذلك غالبًا يعني أن الوقف بعيد جدًا بالنسبة لحسابك، لا أنه عليك استخدام الرافعة.",
  "helpAccountBalance": "استخدم الرصيد الحقيقي اليوم، لا الذي تأمل بلوغه. كل حسابات المخاطرة تستند إلى هذا الرقم، وتقريبه للأعلى يضخّم كل صفقاتك.",
  "helpPipValue": "ما تربحه أو تخسره الصفقة عند تحرك الزوج نقطة واحدة. يعتمد على الزوج وعملة حسابك: نقطة EURUSD لا تساوي نقطة USDJPY.",
  "helpLotSize": "العقد القياسي 100,000 وحدة من العملة الأساس، والميني 10,000 والمايكرو 1,000. نتيجة 0.35 عقد تعني 35,000 وحدة، لا 35.",
  "helpLeverage": "تضاعف النتيجة في الاتجاهين بالتساوي. عند 10 أضعاف، حركة 10% ضدك لا تُبقيك عند 90% — بل تُصفّيك. التصفية تسبق الخسارة الكاملة.",
  "helpContractSize": "كل عقد آجل يمثل كمية ثابتة من الأصل، وتختلف بين الأسواق. عقد E-mini S&P يتحرك 50 دولارًا للنقطة، وعقد النفط 1,000 برميل. هذا المضاعف هو ما يحوّل حركة صغيرة إلى نتيجة كبيرة.",
  "helpSimulations": "كم مرة يُعاد ترتيب صفقاتك عشوائيًا. مع عدد قليل تتغير النتيجة مع كل ضغطة؛ ومن نحو 5,000 تستقر المئينات ويصبح الاعتماد عليها ممكنًا.",
  "helpDrawdown": "أكبر هبوط من قمة الحساب إلى القاع الذي يليها. هذا هو الرقم الذي يحدد فعلاً إن كنت ستلتزم بالنظام: قلّة من يواصلون التداول خلال تراجع لم يتوقعوه.",
