  "stratWinRateTag": "استرشادي",
  "stratWinRateCaveat": "نطاق استرشادي للأسلوب، لا قياس: بلا عيّنة ولا مدة ولا مصدر.",
  "stratWinRateNote": "عن نسب النجاح في هذه الصفحة: هي نطاقات استرشادية يوصَف بها كل أسلوب عادةً، وليست نتائج مقيسة. لا تحمل عيّنة ولا مدة ولا أصلًا ولا مصدرًا، ولذلك لا تصلح لتحديد حجم أي شيء. وحتى لو كانت مقيسة لظلّت وحدها لا تقول الكثير: 45٪ مع أرباح تعادل ثلاثة أضعاف الخسائر تربح مالًا، و70٪ مع خسائر تعادل ثلاثة أضعاف الأرباح تخسره. الذي يحسم هو القيمة المتوقعة — نسبة النجاح × متوسط الربح − نسبة الإخفاق × متوسط الخسارة — لا النسبة المئوية. ونسبتك أنت تخرج من مذكرتك، لا من هذا الجدول.",
